[{"type":"text","text":"<template>
  <div class="grid gap-20 grid-cols-3 p-20">
    <view v-for="(item, index) in fileList" :key="item.filePath" @click="preview(item)">
      <AuthenticatedAttachmentImage
        v-if="imageTypes.includes(item.fileType) && isAuthenticatedImage(item.filePath)"
        :src="retryImageUrl(item.filePath)" :active="pageActive"
        @loading="imageLoading(item)" @loaded="imageLoaded(item, $event)" @error="imageError(item, $event)" />
      <uv-image v-else :key="item.url" width="100%" :src="item.url" :observeLazyLoad="true" @error="imageError(item)"></uv-image>
      <view class="mt-12 text-24 break-all">{{ item.originalFilename || item.fileName || item.materialType || '附件' }}</view>
      <view v-if="failedImages.has(item.filePath)" class="mt-8 text-24">
        {{ imageErrors[item.filePath] || '加载失败，点击重试' }}
        <text class="ml-12 text-blue-500" @click.stop="inspectFailure(item)">查看原因</text>
      </view>
    </view>
    <uv-empty v-if="!fileList.length" mode="list"></uv-empty>
  </div>
