<script setup>
import { previewPdf, downloadAttachment } from '@/utils/index'
import { inspectAttachment, attachmentDiagnosticText } from '@/utils/attachmentDiagnostics'
import fileStore from '@/store/file'
import PDFUrl from '../static/images/pdf.png'
import FileIcon from '../static/images/project/file.png'
import AuthenticatedAttachmentImage from '@/components/AuthenticatedAttachmentImage/AuthenticatedAttachmentImage.vue'
import { isAuthenticatedImage, AttachmentImageError } from '@/utils/authenticatedImage'
import { useClosePreview } from '@/composables/useClosePreview'
// 用来处理图片预览时点击手机自带返回键，关闭图片预览层
useClosePreview()
// 中文说明：材料请求可能晚于页面进入返回，使用计算属性同步列表，并忽略空地址。
const failedImages = ref(new Set())
const pageActive = ref(true)
const localImages = ref({})
const imageErrors = ref({})
const inspecting = ref(false)
const retryVersions = ref({})
let retrySequence = 0
// 中文说明：仅在用户重试失败图片时增加缓存标记，不改变原附件身份参数和鉴权入口。
const retryImageUrl = (path) => {
  const version = retryVersions.value[path]
  if (!version) return path
  const hashIndex = path.indexOf('#')
  const main = hashIndex < 0 ? path : path.slice(0, hashIndex)
  const hash = hashIndex < 0 ? '' : path.slice(hashIndex)
  return `${main}${main.includes('?') ? '&' : '?'}_previewRetry=${encodeURIComponent(version)}${hash}`
}
const imageTypes = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp']
const fileList = computed(() => {
  const files = fileStore.getFiles()
  if (!Array.isArray(files)) return []
  return files.filter(file => typeof file?.filePath === 'string' && file.filePath.trim()).map(file => ({
    ...file,
    filePath: file.filePath.trim(),
    fileType: String(file.fileType || '').trim().toLowerCase(),
    url: String(file.fileType || '').trim().toLowerCase() === 'pdf' ? PDFUrl
      : imageTypes.includes(String(file.fileType || '').trim().toLowerCase()) ? (isAuthenticatedImage(file.filePath.trim()) ? localImages.value[file.filePath.trim()] || FileIcon : retryImageUrl(file.filePath.trim())) : FileIcon,
  }))
})
const preview = (file) => {
  // 未能从历史链接解析出UUID时明确提示，不回退旧匿名接口。
  if (!file.filePath) {
    uni.showToast({ icon: 'none', title: '附件地址不完整，请联系管理员' })
    return
  }
  if (file.fileType === 'pdf') {
    previewPdf(file.filePath)
  } else if (imageTypes.includes(file.fileType)) {
    if (failedImages.value.has(file.filePath)) {
      // 中文说明：此前这里只弹提示，修复后台或会话后也不会重新发请求；现在清除失败状态并重建图片。
      failedImages.value.delete(file.filePath)
      retryVersions.value[file.filePath] = `${Date.now()}-${++retrySequence}`
      uni.showToast({ icon: 'none', title: '正在重新加载附件' })
      return
    }
    if (isAuthenticatedImage(file.filePath) && !localImages.value[file.filePath]) {
      uni.showToast({ icon: 'none', title: '图片正在加载，请稍候' })
      return
    }
    // 中文说明：缩略图与放大预览使用同一Blob，放大时不再重新发出可能缺少凭证的图片请求。
    const images = fileList.value.filter(item => imageTypes.includes(item.fileType)
      && (!isAuthenticatedImage(item.filePath) || localImages.value[item.filePath]))
    uni.previewImage({
      current: images.findIndex(item => item.filePath === file.filePath),
      urls: images.map(item => item.url),
    })
  } else {
    // 中文说明：Word、Excel、压缩包等格式不能在线预览，改为下载。
    downloadAttachment(file.filePath)
  }
}
const imageLoading = (file) => {
  failedImages.value.delete(file.filePath)
  delete localImages.value[file.filePath]
  delete imageErrors.value[file.filePath]
}
const imageLoaded = (file, image) => {
  localImages.value[file.filePath] = image.url
  failedImages.value.delete(file.filePath)
  delete imageErrors.value[file.filePath]
}
const imageError = (file, error) => {
  if (!imageTypes.includes(file.fileType)) return
  delete localImages.value[file.filePath]
  failedImages.value.add(file.filePath)
  imageErrors.value[file.filePath] = error instanceof AttachmentImageError
    ? `${error.message}${error.status ? `（HTTP ${error.status}）` : ''}` : '图片内容无法显示，点击可重试'
}
// 中文说明：错误图片事件没有HTTP状态；用户主动检查时通过HEAD取得状态及追踪号，不下载文件内容。
const inspectFailure = async (file) => {
  if (inspecting.value) return
  inspecting.value = true
  uni.showLoading({ title: '正在检查附件', mask: true })
  try {
    const result = await inspectAttachment(retryImageUrl(file.filePath))
    const content = attachmentDiagnosticText(result)
    uni.hideLoading()
    uni.showModal({
      title: '附件检查结果', content, confirmText: '复制结果', cancelText: '关闭',
      success: (action) => {
        if (action.confirm) uni.setClipboardData({ data: content })
      },
    })
  } catch (error) {
    uni.hideLoading()
    uni.showModal({ title: '附件检查结果', content: error instanceof Error ? error.message : '检查失败', showCancel: false })
  } finally {
    inspecting.value = false
  }
}
onHide(() => {
  pageActive.value = false
  localImages.value = {}
  imageErrors.value = {}
  failedImages.value.clear()
})
onShow(() => {
  pageActive.value = true
  if (fileStore.getPageTitle()) {
    uni.setNavigationBarTitle({
      title: fileStore.getPageTitle(),
    })
  }
})
</script>
"}]

