import { chromium } from 'playwright'

const base = 'http://127.0.0.1:8093/wechatapph5/'
// 两个超长数字文件名，模拟“决策相关材料”重叠场景
const filesPayload = {
  files: [
    { filePath: 'https://example.com/a.jpg', fileType: 'jpg', originalFilename: '2026090913162024.jpg', fileName: '2026090913162024.jpg' },
    { filePath: 'https://example.com/b.jpg', fileType: 'jpg', originalFilename: '2026090913162424.jpeg', fileName: '2026090913162424.jpeg' },
    { filePath: 'https://example.com/c.jpg', fileType: 'jpg', originalFilename: '202609101422334455666777888.jpeg', fileName: 'x.jpeg' },
  ],
  pageTitle: '决策相关材料',
}

const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()
await page.addInitScript((payload) => {
  try { localStorage.setItem('file', JSON.stringify(payload)) } catch (e) {}
}, filesPayload)

const target = base + '#/pages/files'
await page.goto(target, { waitUntil: 'networkidle', timeout: 30000 }).catch(() => {})
await page.waitForTimeout(2500)
// 尝试隐藏图片的加载失败占位影响；直接截当前页面
await page.screenshot({ path: 'D:/repository/家园区一网通办/.tmp-bug6477/after.png', fullPage: false })

// 读取文件名元素的实际盒子，判断是否越界/重叠
const info = await page.evaluate(() => {
  const all = Array.from(document.querySelectorAll('*'))
  const nameEls = all.filter(el => /\.jpe?g$/i.test((el.textContent || '').trim()) && el.children.length === 0)
  return nameEls.map(el => {
    const r = el.getBoundingClientRect()
    const cs = getComputedStyle(el)
    return { text: el.textContent.trim(), left: Math.round(r.left), right: Math.round(r.right), width: Math.round(r.width), wordBreak: cs.wordBreak, overflowWrap: cs.overflowWrap, whiteSpace: cs.whiteSpace }
  })
})
console.log(JSON.stringify({ url: page.url(), boxWidth: 390, names: info }, null, 2))
await browser.close()

